// Turns an approved plan-mode plan (markdown) into stages and steps:
// headings become stages, top-level list items become steps.

import type { HeadwayOutline } from '../types'
import { clean } from './clean'
import { isSameStep, words } from './match'

export const MAX_STAGES = 20
export const MAX_STEPS = 100
export const MAX_TITLE = 120

const HEADING = /^ {0,3}(#{1,6})\s+(.*?)\s*#*\s*$/
const ITEM = /^( *)(?:[-*+]|\d{1,3}[.)])\s+(?:\[[ xX]\]\s+)?(.*\S)\s*$/
const FENCE = /^\s*(```|~~~)/

// Sections that describe the plan rather than steps of it.
const NOT_WORK =
  /^(context|background|overview|summary|goals?|non[- ]?goals?|notes?|risks?|open questions|questions|assumptions|references|out of scope|alternatives( considered)?|(critical |key |relevant )?files( to (change|modify|touch|edit))?|dependencies)\b/i

/**
 * Every title and stage name Headway draws passes through here, from every
 * source: controls and escapes go first (clean), then markdown emphasis,
 * code ticks and link targets; the length is capped.
 */
export function cleanText(text: string): string {
  const plain = clean(text)
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[*_`~]+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  return [...plain].length > MAX_TITLE ? [...plain].slice(0, MAX_TITLE - 1).join('') + '…' : plain
}

/** A heading as a stage name: "Phase 1: Build the API" reads "Build the API". */
export function stageName(heading: string): string {
  const text = cleanText(heading)
  const bare = text
    .replace(/^(phase|stage|step|part|milestone)\s+[\w.]+\s*[:.)-]\s*/i, '')
    .replace(/^\d+[.):]\s*/, '')
    .replace(/[:.]$/, '')
    .trim()
  return bare === '' ? text : bare
}

/** A list item as a step title: a bold lead-in wins, else the whole item. */
export function stepTitle(item: string): string {
  const lead = /^\*\*(.+?)\*\*/.exec(item) ?? /^__(.+?)__/.exec(item)
  const text = cleanText(lead?.[1] ?? item)
  return text.replace(/[:.]$/, '').trim()
}

/**
 * Reads the plan's outline. The stage level is the shallowest heading level
 * used at least twice; sections such as Context or Risks are left out, and
 * only top-level items count (sub-bullets are detail). Fewer than two stages
 * with steps reads as one flat stage. Null when the plan lists no steps.
 */
export function parseOutline(markdown: string): HeadwayOutline | null {
  const lines = markdown.split(/\r?\n/)
  const isCode: boolean[] = []
  let inFence = false
  for (const line of lines) {
    const isFence = FENCE.test(line)
    isCode.push(inFence || isFence)
    if (isFence) inFence = !inFence
  }

  const levels = new Map<number, number>()
  lines.forEach((line, n) => {
    const heading = isCode[n] ? null : HEADING.exec(line)
    if (heading?.[1]) levels.set(heading[1].length, (levels.get(heading[1].length) ?? 0) + 1)
  })
  const stageLevel = [...levels.entries()]
    .filter(([, count]) => count >= 2)
    .map(([level]) => level)
    .sort((a, b) => a - b)[0]

  const stages: { name: string; steps: string[] }[] = []
  const loose: string[] = []
  let current: { name: string; steps: string[] } | null = null
  // A non-work section hides its items: at the stage level, or as a sub-heading inside a stage.
  let isStageSkipped = false
  let isSubSkipped = false

  lines.forEach((line, n) => {
    if (isCode[n]) return
    const heading = HEADING.exec(line)
    if (heading?.[1] && heading[2] !== undefined) {
      const level = heading[1].length
      const skip = NOT_WORK.test(cleanText(heading[2]))
      if (stageLevel !== undefined && level === stageLevel) {
        current = skip ? null : { name: stageName(heading[2]), steps: [] }
        if (current) stages.push(current)
        isStageSkipped = skip
        isSubSkipped = false
      } else if (stageLevel !== undefined && level < stageLevel) {
        // A heading above the stage level (the plan's title) ends any stage.
        current = null
        isStageSkipped = skip
        isSubSkipped = false
      } else {
        isSubSkipped = skip
      }
      return
    }
    const item = ITEM.exec(line)
    if (!item || item[2] === undefined || (item[1] ?? '').length > 1 || isStageSkipped || isSubSkipped) return
    const title = stepTitle(item[2])
    if (title === '') return
    if (current) current.steps.push(title)
    else loose.push(title)
  })

  const staged = stages.filter(stage => stage.steps.length > 0).slice(0, MAX_STAGES)
  if (staged.length >= 2) {
    const steps = staged.flatMap((stage, index) => stage.steps.map(title => ({ title, stage: index })))
    return { stages: staged.map(stage => stage.name), steps: steps.slice(0, MAX_STEPS) }
  }
  const flat = [...staged.flatMap(stage => stage.steps), ...loose].slice(0, MAX_STEPS)
  return flat.length === 0 ? null : { stages: [''], steps: flat.map(title => ({ title, stage: 0 })) }
}

/**
 * Which outline stage a tracked step belongs to: the stage of the outline
 * step it matches, else a stage whose name's words all appear in it; null
 * when neither.
 */
export function stageOfTitle(title: string, outline: HeadwayOutline): number | null {
  const step = outline.steps.find(candidate => isSameStep(candidate.title, title))
  if (step) return step.stage
  const titleWords = new Set(words(title))
  const index = outline.stages.findIndex(name => {
    const nameWords = words(name)
    return nameWords.length > 0 && nameWords.every(word => titleWords.has(word))
  })
  return index >= 0 ? index : null
}

/**
 * Stages for a tracked list: an outline's stages when at least one step
 * matches them (an unmatched step takes the stage of the step before it),
 * else one flat stage.
 */
export function stageList(titles: readonly string[], outline: HeadwayOutline | null): { stages: string[]; stageOf: number[] } {
  const flat = { stages: [''], stageOf: titles.map(() => 0) }
  if (!outline || outline.stages.length < 2) return flat
  let hits = 0
  let previous = 0
  const stageOf = titles.map(title => {
    const stage = stageOfTitle(title, outline)
    if (stage === null) return previous
    hits += 1
    previous = stage
    return stage
  })
  return hits === 0 ? flat : { stages: outline.stages, stageOf }
}

files.hooks/clean.ts:
// The one cleaner for text Headway draws that came from outside it: step
// titles and stage names out of Claude's todo, task and plan-mode tools.
// The engine refuses a drawn tree whose text holds a control character and
// draws its own instead, and since Headway wraps the band mods beneath it,
// one stray escape in a title would take their lines (and buttons) down too.

// ANSI escape sequences: CSI (ESC [ or its one-byte form U+009B) with its
// parameters, a terminated string (OSC, DCS, SOS, PM, APC; a hyperlink keeps
// its text), then any other ESC with the bytes that belong to it (a space
// after a stray ESC is kept as text).
const ANSI =
  /(?:\u001b\[|\u009b)[0-?]*[ -/]*[@-~]|(?:\u001b[\]PX^_]|[\u0090\u0098\u009d-\u009f])[^\u0007\u001b\u009c]*(?:\u0007|\u001b\\|\u009c)|\u001b[!-/]*[0-~]?/g
// Line breaks and tabs read as a space (titles are one line).
const BREAKS = /[\t\n\v\f\r\u0085\u2028\u2029]/g
// Every other C0 control, DEL and every C1 control.
const CONTROLS = /[\u0000-\u001f\u007f-\u009f]/g
// Invisible marks that can reorder or hide text: bidi embeddings, overrides
// and isolates, zero-width characters, word joiners, the BOM, soft hyphens.
const INVISIBLE = /[\u00ad\u061c\u180e\u200b-\u200f\u202a-\u202e\u2060-\u2064\u2066-\u2069\ufeff]/g

/** Text safe to draw: escape sequences gone, breaks as spaces, controls and invisible marks removed. */
export function clean(text: string): string {
  return text.replace(ANSI, '').replace(BREAKS, ' ').replace(CONTROLS, '').replace(INVISIBLE, '')
}

files.types/index.d.ts:
// Headway's state contract. `done` is the public "plan done" signal other
// mods may read or react to; `run` is Headway's own working state and may
// change shape between versions.

/** Where the plan came from: a TodoWrite list, the Task tools, or an approved plan-mode plan alone. */
export type HeadwaySource = 'todo' | 'task' | 'outline'

export type HeadwayStepStatus = 'pending' | 'active' | 'done'

export type HeadwayStep = {
  /** Identity across rewrites: `task:<id>` for a task, a minted `t<n>` for a todo item. */
  key: string
  title: string
  /** Index into the plan's `stages`. */
  stage: number
  status: HeadwayStepStatus
  /** Working time the step took, in ms; absent when it was already done when Headway first saw it. */
  ms?: number
}

/** This project's pace from earlier sessions: the median step time and how many steps it rests on. */
export type HeadwayPrior = { medianMs: number; count: number }

export type HeadwayPlan = {
  id: number
  source: HeadwaySource
  /** Stage names; a single '' for a flat list. */
  stages: string[]
  steps: HeadwayStep[]
  /** Plan-clock ms (working time only) when the plan started. */
  startedAt: number
  /** Plan-clock ms of the last step completion, or the start. */
  lastMarkAt: number
  /** The last completions that share one span (several steps marked done together). */
  batch?: { start: number; keys: string[] }
  /** True once the plan was seen with a step still to do. */
  wasOpen: boolean
  nextKey: number
  projectKey?: string
  prior?: HeadwayPrior
  /** The total the first honest estimate predicted, in ms. */
  firstEstimateMs?: number
  /** A replan's flash: steps added and removed, shown until `until` (wall ms). */
  revised?: { added: number; removed: number; until: number }
  /** Wall ms when the last step finished; the green flash runs from here. */
  finishedAt?: number
  totalMs?: number
  receipt?: string
}

/** An approved plan-mode plan, reduced to stage names and step titles. */
export type HeadwayOutline = { stages: string[]; steps: { title: string; stage: number }[] }

export type HeadwayRun = {
  plan: HeadwayPlan | null
  outline: HeadwayOutline | null
  /** The plan clock: working ms banked, and the wall ms the current working span began (null while idle). */
  clock: { activeMs: number; since: number | null }
  /** True while the main loop's turn runs. */
  turn: boolean
  /** Ids of the subagents running now. */
  agents: string[]
  /** Ids that ended before their start was seen (kept briefly so the count never goes wrong). */
  ended: string[]
  /** This session's finished step times, in ms. */
  durations: number[]
  hidden: boolean
  /** The last plan id handed out. */
  seq: number
  /** Claude's turns begun since it last updated its plan; at QUIET_TURNS an unfinished plan leaves. */
  quiet: number
}

/**
 * Written once each time a plan finishes. Counts and durations only, never titles.
 * Read it with `$.state.get({ plugin: 'headway', key: 'done' })` (a render hook
 * that reads it redraws when it changes), or hook `state.set` with the matcher
 * `{ plugin: 'headway', key: 'done' }` to react the moment it is written.
 */
export type HeadwayDone = {
  /** Which plan of this session finished; grows by one or more per plan. */
  seq: number
  /** Wall-clock ms when it finished. */
  at: number
  /** Working time from the plan's start to its last step, in ms. */
  totalMs: number
  steps: number
  /** Working ms per stage, in stage order (one entry for a flat list). */
  stageMs: number[]
  /** The total the first estimate predicted, or null when none was shown. */
  estimateMs: number | null
}

declare module 'claude-code' {
  interface PluginState {
    headway: { run: HeadwayRun; done: HeadwayDone | null }
  }
}
